<script setup>
import{ref,reactive,onMounted}from'vue';import{useRoute}from'vue-router';import api from'../services/api.js';import PageHero from'../components/PageHero.vue';import GuideCard from'../components/GuideCard.vue'
const route=useRoute(),loading=ref(false),data=ref({records:[],total:0}),destinations=ref([]);const query=reactive({page:1,size:12,keyword:route.query.keyword||'',destinationId:'',days:'',maxBudget:'',audience:'',sort:route.query.sort||'recommended'});const load=async()=>{loading.value=true;try{data.value=await api.get('/public/guides',{params:query})}finally{loading.value=false}};const reset=()=>{Object.assign(query,{page:1,keyword:'',destinationId:'',days:'',maxBudget:'',audience:'',sort:'recommended'});load()};onMounted(async()=>{destinations.value=await api.get('/public/destinations');load()})
</script>
<template><PageHero image="/uploads/demo/banners/banner-002.png" eyebrow="TRAVEL GUIDES" title="一篇好攻略，能让出发更轻松" subtitle="从真实路线、预算和交通开始筛选，找到适合自己节奏的旅行方式。"/><div class="container guide-list-page"><div class="filter-bar"><el-input v-model="query.keyword" clearable placeholder="搜索攻略标题或摘要" @keyup.enter="query.page=1;load()"/><el-select v-model="query.destinationId" clearable filterable placeholder="目的地"><el-option v-for="d in destinations" :key="d.id" :label="d.name" :value="d.id"/></el-select><el-select v-model="query.days" clearable placeholder="旅行天数"><el-option v-for="d in 7" :key="d" :label="`${d} 天`" :value="d"/></el-select><el-select v-model="query.maxBudget" clearable placeholder="最高预算"><el-option label="¥1,000 以内" :value="1000"/><el-option label="¥3,000 以内" :value="3000"/><el-option label="¥5,000 以内" :value="5000"/><el-option label="¥10,000 以内" :value="10000"/></el-select><el-select v-model="query.audience" clearable placeholder="适合人群"><el-option v-for="x in ['学生党','情侣','亲子家庭','摄影爱好者','第一次自由行']" :key="x" :label="x" :value="x"/></el-select><el-button type="primary" @click="query.page=1;load()">筛选</el-button><el-button @click="reset">重置</el-button></div><div class="sort-row"><p>共找到 <b>{{data.total}}</b> 篇公开攻略</p><el-radio-group v-model="query.sort" size="small" @change="query.page=1;load()"><el-radio-button label="recommended">综合推荐</el-radio-button><el-radio-button label="latest">最新发布</el-radio-button><el-radio-button label="views">最多浏览</el-radio-button><el-radio-button label="likes">最多点赞</el-radio-button></el-radio-group></div><div v-loading="loading" class="guide-grid"><GuideCard v-for="guide in data.records" :key="guide.id" :guide="guide"/></div><div v-if="!loading&&!data.records.length" class="empty-panel">暂时没有符合条件的攻略，换一组筛选条件试试。</div><div class="pagination-wrap"><el-pagination background layout="prev,pager,next" :total="data.total" :page-size="query.size" v-model:current-page="query.page" @current-change="load"/></div></div></template>
<style scoped>.guide-list-page{padding:18px 0 80px}.filter-bar{display:grid;grid-template-columns:1.4fr repeat(4,1fr) auto auto}.sort-row{display:flex;justify-content:space-between;align-items:center;margin:24px 0}.sort-row p{color:#72868a}.sort-row b{font-size:20px;color:#167c8c}@media(max-width:950px){.filter-bar{grid-template-columns:repeat(3,1fr)}.sort-row{display:grid;gap:12px;overflow:auto}}@media(max-width:600px){.filter-bar{grid-template-columns:1fr}.sort-row .el-radio-group{display:flex;overflow:auto}.sort-row :deep(.el-radio-button__inner){white-space:nowrap}}</style>

